    put_service_readiness(service_readiness)
    put_admission_guard(admission_guard)
  }


  /** helper function to check RequestAdmission_supervisor_process_request_admission's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param lifecycle_admission method that will be called with the value of the outgoing data
   *        port 'lifecycle_admission'.
   * @param gate_admission method that will be called with the value of the outgoing data
   *        port 'gate_admission'.
   * @param docking_admission method that will be called with the value of the outgoing data
   *        port 'docking_admission'.
   * @param access_admission method that will be called with the value of the outgoing data
   *        port 'access_admission'.
   * @param undocking_admission method that will be called with the value of the outgoing data
   *        port 'undocking_admission'.
   * @param request_disposition method that will be called with the value of the outgoing data
   *        port 'request_disposition'.
   */
  def check_concrete_output(lifecycle_admission: Docking_Access_Supervisor.AdmissionDecision => B,
                            gate_admission: Docking_Access_Supervisor.AdmissionDecision => B,
                            docking_admission: Docking_Access_Supervisor.AdmissionDecision => B,
                            access_admission: Docking_Access_Supervisor.AdmissionDecision => B,
                            undocking_admission: Docking_Access_Supervisor.AdmissionDecision => B,
                            request_disposition: Docking_Access_Supervisor.RequestDisposition.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val lifecycle_admissionValue: Docking_Access_Supervisor.AdmissionDecision = get_lifecycle_admission().get
    if(!lifecycle_admission(lifecycle_admissionValue)) {
      testFailures = testFailures :+ st"'lifecycle_admission' did not match expected: value of the outgoing data port is ${lifecycle_admissionValue}"
    }
    val gate_admissionValue: Docking_Access_Supervisor.AdmissionDecision = get_gate_admission().get
    if(!gate_admission(gate_admissionValue)) {
      testFailures = testFailures :+ st"'gate_admission' did not match expected: value of the outgoing data port is ${gate_admissionValue}"
    }
    val docking_admissionValue: Docking_Access_Supervisor.AdmissionDecision = get_docking_admission().get
    if(!docking_admission(docking_admissionValue)) {
      testFailures = testFailures :+ st"'docking_admission' did not match expected: value of the outgoing data port is ${docking_admissionValue}"
    }
    val access_admissionValue: Docking_Access_Supervisor.AdmissionDecision = get_access_admission().get
    if(!access_admission(access_admissionValue)) {
      testFailures = testFailures :+ st"'access_admission' did not match expected: value of the outgoing data port is ${access_admissionValue}"
    }
    val undocking_admissionValue: Docking_Access_Supervisor.AdmissionDecision = get_undocking_admission().get
    if(!undocking_admission(undocking_admissionValue)) {
      testFailures = testFailures :+ st"'undocking_admission' did not match expected: value of the outgoing data port is ${undocking_admissionValue}"
    }
    val request_dispositionValue: Docking_Access_Supervisor.RequestDisposition.Type = get_request_disposition().get
    if(!request_disposition(request_dispositionValue)) {
      testFailures = testFailures :+ st"'request_disposition' did not match expected: value of the outgoing data port is ${request_dispositionValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


